node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Find Everyday Crew Tee
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Crew Tee%'\").all();
for (const p of products) {
  console.log('=== Product:', p.name, '| ID:', p.product_id, '===');
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
  for (const v of variants) {
    const opts = v.options ? JSON.parse(v.options) : {};
    console.log('  Variant:', v.item_id, '| Price: \$' + Number(v.price).toFixed(2), '| Available:', !!v.available, '| Options:', JSON.stringify(opts));
  }
}
db.close();
"

